        for line in open(f):
            m = re.search(r'(req-\d+)', line)
            if not m:
                continue
            rid = m.group(1)
            if re.search(r'\bstart\b', line):
                started.add(rid)
            if re.search(r'\bERROR\b', line):
                errored.add(rid)
            if re.search(r'\bdone\b', line):
                done.add(rid)
    expected = sorted(r for r in started if r in errored and r not in done)
    if not os.path.exists('out/stuck.txt'):
        return "FAIL: out/stuck.txt missing"
    got = [l.strip() for l in open('out/stuck.txt') if l.strip()]
    if got != expected:
        return "FAIL: file has %s, expected %s" % (got, expected)
    if got != sorted(got):
        return "FAIL: not sorted"
    print("PASS: out/stuck.txt matches expected %d ids: %s" % (len(got), got))
    return "PASS"
return check()
